/** Project pick dispositions from the latest finalized PROJECT_ASSIGNMENT run. */
async function getProjectDispositions(
  podHeadId: string
): Promise<Map<string, "PRIMARY_HONORED" | "SECONDARY_HONORED" | "FELL_BACK_TO_BALANCE">> {
  const run = await db.matchingRun.findFirst({
    where: { type: "PROJECT_ASSIGNMENT", isFinalized: true, status: "COMPLETED" },
    orderBy: { startedAt: "desc" },
    select: { stats: true }
  });
  const out = new Map<string, "PRIMARY_HONORED" | "SECONDARY_HONORED" | "FELL_BACK_TO_BALANCE">();
  if (!run) return out;
  const stats = run.stats as Record<string, unknown> | null;
  const dispositions = (stats?.dispositions ?? []) as Array<{
    podHeadId: string;
    projectId: string;
    outcome: "PRIMARY_HONORED" | "SECONDARY_HONORED" | "FELL_BACK_TO_BALANCE";
  }>;
  for (const d of dispositions) {
    if (d.podHeadId === podHeadId) {
      out.set(d.projectId, d.outcome);
    }
  }
  return out;
}

// === Public result shapes ===

export interface AssignedPodHead {
  id: string;
  name: string;
  email: string;
  bio: string | null;
  skills: string[];
  pitch: string;
  rankAchieved: number | null; // null when auto-assigned
  theirRankOfYou: number | null;
  autoGenerated: boolean;
}

export interface AssignedOrch {
  id: string;
  name: string;
  email: string;
  bio: string | null;
  pitch: string;
  rankAchieved: number | null;
  theirRankOfYou: number | null;
  autoGenerated: boolean;
}

export interface AssignedAgent {
  id: string;
  name: string;
  email: string;
  bio: string | null;
  skills: string[];
  pitch: string;
  rankAchieved: number | null;
  theirRankOfYou: number | null;
  autoGenerated: boolean;
}

export interface AssignedProject {
  id: string;
  title: string;
  description: string;
  tags: string[];
  outcome: "PRIMARY_HONORED" | "SECONDARY_HONORED" | "FELL_BACK_TO_BALANCE";
}

export interface PodMate {
  id: string;
  name: string;
  email: string;
  bio: string | null;
  skills: string[];
  pitch: string;
}

// === Agent results ===

export interface AgentResults {
  assignedPodHead: AssignedPodHead | null;
  orchAbove: { id: string; name: string; email: string; pitch: string } | null;
  podMates: PodMate[];
  projects: { id: string; title: string; description: string; tags: string[] }[];
}

export async function getAgentResults(userId: string): Promise<AgentResults> {
  const agent = await db.agentProfile.findUnique({
    where: { userId },
    select: { id: true, assignedPodHeadId: true }
  });
  if (!agent || !agent.assignedPodHeadId) {
    return { assignedPodHead: null, orchAbove: null, podMates: [], projects: [] };
  }

  const ph = await db.podHeadProfile.findUnique({
    where: { id: agent.assignedPodHeadId },
    select: {
      id: true,
      bio: true,
      skills: true,
      pitch: true,
      assignedOrchId: true,
      user: { select: { name: true, email: true } },
      assignedAgents: {
        where: { id: { not: agent.id } },
        select: {
          id: true,
          bio: true,
          skills: true,
          pitch: true,
          user: { select: { name: true, email: true } }
        }
      },
      projectPicks: {
        where: { assigned: true },
        orderBy: { rank: "asc" },
        include: { project: true }
      }
    }
  });
  if (!ph) {
    return { assignedPodHead: null, orchAbove: null, podMates: [], projects: [] };
  }

  const [myRankOfPh, phRankOfMe] = await Promise.all([
    agentToPodHeadRank(agent.id, ph.id),
    podHeadToAgentRank(ph.id, agent.id)
  ]);

  let orchAbove: AgentResults["orchAbove"] = null;
  if (ph.assignedOrchId) {
    const orch = await db.orchProfile.findUnique({
      where: { id: ph.assignedOrchId },
      select: {
        id: true,
        pitch: true,
        user: { select: { name: true, email: true } }
      }
    });
    if (orch) {
      orchAbove = {
        id: orch.id,
        name: orch.user.name,
        email: orch.user.email,
        pitch: orch.pitch
      };
    }
  }

  return {
    assignedPodHead: {
      id: ph.id,
      name: ph.user.name,
      email: ph.user.email,
      bio: ph.bio,
      skills: ph.skills,
      pitch: ph.pitch,
      rankAchieved: myRankOfPh.rank,
      theirRankOfYou: phRankOfMe.rank,
      autoGenerated: myRankOfPh.autoGenerated || phRankOfMe.autoGenerated
    },
    orchAbove,
    podMates: ph.assignedAgents.map((a) => ({
      id: a.id,
      name: a.user.name,
      email: a.user.email,
      bio: a.bio,
      skills: a.skills,
      pitch: a.pitch
    })),
    projects: ph.projectPicks.map((pp) => ({
      id: pp.project.id,
      title: pp.project.title,
      description: pp.project.description,
      tags: pp.project.tags
    }))
  };
}

// === Pod Head results ===

export interface PodHeadResults {
  assignedOrch: AssignedOrch | null;
  assignedAgents: AssignedAgent[];
  assignedProjects: AssignedProject[];
}

export async function getPodHeadResults(userId: string): Promise<PodHeadResults> {
  const ph = await db.podHeadProfile.findUnique({
    where: { userId },
    select: {
      id: true,
      assignedOrchId: true,
      assignedAgents: {
        select: {
          id: true,
          bio: true,
          skills: true,
          pitch: true,
          user: { select: { name: true, email: true } }
        }
      },
      projectPicks: {
        where: { assigned: true },
        orderBy: { rank: "asc" },
        include: { project: true }
      }
    }
  });
  if (!ph) {
    return { assignedOrch: null, assignedAgents: [], assignedProjects: [] };
  }

  // Assigned Orch with mutual ranks
  let assignedOrch: AssignedOrch | null = null;
  if (ph.assignedOrchId) {
    const orch = await db.orchProfile.findUnique({
      where: { id: ph.assignedOrchId },
      select: {
        id: true,
        bio: true,
        pitch: true,
        user: { select: { name: true, email: true } }
      }
    });
    if (orch) {
      const [myRank, theirRank] = await Promise.all([
        podHeadToOrchRank(ph.id, orch.id),
        orchToPodHeadRank(orch.id, ph.id)
      ]);
      assignedOrch = {
        id: orch.id,
        name: orch.user.name,
        email: orch.user.email,
        bio: orch.bio,
        pitch: orch.pitch,
        rankAchieved: myRank.rank,
        theirRankOfYou: theirRank.rank,
        autoGenerated: myRank.autoGenerated || theirRank.autoGenerated
      };
    }
  }

  // Assigned Agents with mutual ranks
  const assignedAgents: AssignedAgent[] = await Promise.all(
    ph.assignedAgents.map(async (a) => {
      const [myRank, theirRank] = await Promise.all([
        podHeadToAgentRank(ph.id, a.id),
        agentToPodHeadRank(a.id, ph.id)
      ]);
      return {
        id: a.id,
        name: a.user.name,
        email: a.user.email,
        bio: a.bio,
        skills: a.skills,
        pitch: a.pitch,
        rankAchieved: myRank.rank,
        theirRankOfYou: theirRank.rank,
        autoGenerated: myRank.autoGenerated || theirRank.autoGenerated
      };
    })
  );

  // Projects with disposition outcomes
  const dispositions = await getProjectDispositions(ph.id);
  const assignedProjects: AssignedProject[] = ph.projectPicks.map((pp) => ({
    id: pp.project.id,
    title: pp.project.title,
    description: pp.project.description,
    tags: pp.project.tags,
    outcome: dispositions.get(pp.project.id) ?? "PRIMARY_HONORED"
  }));

  return { assignedOrch, assignedAgents, assignedProjects };
}

// === Orch results ===

export interface OrchPodHeadEntry {
  id: string;
  name: string;
  email: string;
  bio: string | null;
  skills: string[];
  pitch: string;
  rankAchieved: number | null;
  theirRankOfYou: number | null;
  autoGenerated: boolean;
  agents: PodMate[];
  projects: { id: string; title: string; tags: string[] }[];
}

export interface OrchResults {
  assignedPodHeads: OrchPodHeadEntry[];
}

export async function getOrchResults(userId: string): Promise<OrchResults> {
  const orch = await db.orchProfile.findUnique({
    where: { userId },
    select: {
      id: true,
      assignedPodHeads: {
        select: {
          id: true,
          bio: true,
          skills: true,
          pitch: true,
          user: { select: { name: true, email: true } },
          assignedAgents: {
            select: {
              id: true,
              bio: true,
              skills: true,
              pitch: true,
              user: { select: { name: true, email: true } }
            }
          },
          projectPicks: {
            where: { assigned: true },
            orderBy: { rank: "asc" },
            include: { project: true }
          }
        }
      }
    }
  });
  if (!orch) return { assignedPodHeads: [] };

  const assignedPodHeads: OrchPodHeadEntry[] = await Promise.all(
    orch.assignedPodHeads.map(async (ph) => {
      const [myRank, theirRank] = await Promise.all([
        orchToPodHeadRank(orch.id, ph.id),
        podHeadToOrchRank(ph.id, orch.id)
      ]);
      return {
        id: ph.id,
        name: ph.user.name,
        email: ph.user.email,
        bio: ph.bio,
        skills: ph.skills,
        pitch: ph.pitch,
        rankAchieved: myRank.rank,
        theirRankOfYou: theirRank.rank,
        autoGenerated: myRank.autoGenerated || theirRank.autoGenerated,
        agents: ph.assignedAgents.map((a) => ({
          id: a.id,
          name: a.user.name,
          email: a.user.email,
          bio: a.bio,
          skills: a.skills,
          pitch: a.pitch
        })),
        projects: ph.projectPicks.map((pp) => ({
          id: pp.project.id,
          title: pp.project.title,
          tags: pp.project.tags
        }))
      };
    })
  );

  return { assignedPodHeads };
}
